INSERT INTO resolve.knowledge_articles(id,article_key,language,title,content,aliases,source_url,reviewed_at,version,scope) VALUES
 ('90000000-0000-0000-0000-000000000001','self-care','en','HUTCH self-care','HUTCH publicly describes self-care features for account management, usage and activity history, package activation, bill payments, multiple numbers and complaint registration.','{selfcare,account,usage,activity,package,activate,bill,complaint,"swayan seva","suya sevai"}','https://hutch.lk/hutch-self-care/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000002','usage-history','en','Usage history','HUTCH self-care publicly lists usage and activity history. This describes a public feature and does not promise that every network record is immediately available.','{usage,history,data,activity,consumption,"bhawithaya","payanpaadu"}','https://hutch.lk/hutch-self-care/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000003','complaint-registration','en','Complaint registration','HUTCH self-care publicly lists complaint registration. The public description does not specify the internal ticket system or processing time.','{complaint,register,case,support,"service issue","peminiiliya","pukaar"}','https://hutch.lk/hutch-self-care/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000004','package-activation','en','Package activation','HUTCH self-care publicly lists plan activation. Available packages, eligibility and completion status should be checked in the current customer channel.','{package,plan,bundle,activation,"paeketaya","thoguppu"}','https://hutch.lk/hutch-self-care/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000005','bill-payment','en','Bill payments','HUTCH self-care publicly lists bill payments. This public feature description does not state a payment result or account posting.','{bill,pay,payment,invoice,"bilpatha","pattiyal"}','https://hutch.lk/hutch-self-care/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000006','multiple-numbers','en','Multiple numbers','HUTCH self-care publicly describes managing multiple numbers. Resolve must still verify account ownership before showing private line information.','{"multiple numbers","manage numbers",lines,"anka","enn"}','https://hutch.lk/hutch-self-care/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000007','prepaid-recharge','en','Prepaid recharge','HUTCH online recharge publicly supports prepaid recharge. A payment result and a credited account balance are distinct states.','{prepaid,recharge,"top up",load,"peragevum","munpanam recharge"}','https://hutch.lk/faq-online-web-recharge/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000008','postpaid-recharge','en','Postpaid payments','HUTCH online recharge publicly describes postpaid payment. A submitted payment should not be described as posted until the relevant account record confirms it.','{postpaid,"pay bill",recharge,settlement,"pasugevum","pinpanam"}','https://hutch.lk/faq-online-web-recharge/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000009','online-package-activation','en','Online package activation','HUTCH online recharge publicly lists package activation. The current transaction response is needed to confirm an individual activation.','{online,package,bundle,activation,recharge,"margagatha paketaya","online thoguppu"}','https://hutch.lk/faq-online-web-recharge/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000010','transaction-confirmation','en','Transaction results','The HUTCH online recharge page describes transaction results and confirmation. For an individual query, check its actual payment and fulfilment records separately.','{transaction,result,confirmation,status,"ganudenuwa","parivarthanai"}','https://hutch.lk/faq-online-web-recharge/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000011','online-recharge-fee','en','Online recharge fee','HUTCH FAQ says its online web recharge portal does not add a HUTCH recharge fee. This statement does not determine third-party bank or card fees.','{fee,charge,cost,"online recharge","gasthuwa","kattanam"}','https://hutch.lk/faq-online-web-recharge/','2026-10-02',1,'PUBLIC'),
 ('90000000-0000-0000-0000-000000000012','languages','en','Language access','HUTCH self-care publicly describes access in Sinhala, Tamil and English. Internal support channel language handling is not specified by that public page.','{language,Sinhala,Tamil,English,trilingual,"bhashawa","mozhi"}','https://hutch.lk/hutch-self-care/','2026-10-02',1,'PUBLIC')
